    /**
     * Tests creating a new AdSlot.
     *
     * @return    AdSlot
     */
    public AdSlot testCreate() throws Throwable {
    AdSlot entity = null;

    LOGGER.info( "AdSlotTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a AdSlot");

    StringBuilder msg = new StringBuilder( "-- Failed to create a AdSlot" );

    try {
        entity = service.createAdSlot( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getAdSlotId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a AdSlot with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

