    /**
     * Tests getting all AdSlots.
     *
     * @return    Collection
     */
    public List<AdSlot> testGetAll() throws Throwable {
    LOGGER.info( "AdSlotTest:testGetAll() - Retrieving Collection of AdSlots:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all AdSlot : " );
    List<AdSlot> collection  = null;

    try {
        // call the static get method on the AdSlotService
        collection = service.getAllAdSlot();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            AdSlot currEntity  = null;
            Iterator<AdSlot> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getAdSlotId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

